(7355703, 1151266, 65858, '<td valign="top">Great shot, really lovely as a book cover - my top pick in this challenge!</td>', 'Great shot, really lovely as a book cover - my top pick in this challenge!', '2015-06-01 01:30:47.000000', NULL, 1),
