(7358411, 1151005, 150277, '<td valign="top">I like the image a lot, although I had trouble relating the title to the image - which seemed really sci fi.  (No sci fi to the book title you made me think of.) But lovely book cover.</td>', 'I like the image a lot, although I had trouble relating the title to the image - which seemed really sci fi.  (No sci fi to the book title you made me think of.) But lovely book cover.', '2015-06-08 00:16:11.000000', NULL, 1),
(7358412, 1150716, 150277, '<td valign="top">I love the pop of strong color against white. (Is apple spelled differently in a different language?)  Also recipe should be plural to actually have successful sales I think. But wonderful image and it worked as a book cover to me.</td>', 'I love the pop of strong color against white. (Is apple spelled differently in a different language?)  Also recipe should be plural to actually have successful sales I think. But wonderful image and it worked as a book cover to me.', '2015-06-08 00:18:10.000000', NULL, 1),
