(7358416, 1151348, 150277, '<td valign="top">I know the book title isn''t on this book cover, but I found the image really compelling.</td>', 'I know the book title isn''t on this book cover, but I found the image really compelling.', '2015-06-08 00:20:46.000000', NULL, 1),
(7358417, 1151239, 150277, '<td valign="top">I thought this was wonderful.  Very calm, yet the lighting adds just a bit of drama.  I was actually expecting some sort of thriller or mystery book.</td>', 'I thought this was wonderful.  Very calm, yet the lighting adds just a bit of drama.  I was actually expecting some sort of thriller or mystery book.', '2015-06-08 00:21:49.000000', NULL, 1),
(7358418, 1151279, 150277, '<td valign="top">Works well for me as a book cover, I would at least read the plot summary and maybe the first few pages.  (Cover suggests maybe a bit more horror than I can read, but for fans of the genre I would think this is perfect.)</td>', 'Works well for me as a book cover, I would at least read the plot summary and maybe the first few pages.  (Cover suggests maybe a bit more horror than I can read, but for fans of the genre I would think this is perfect.)', '2015-06-08 00:23:45.000000', NULL, 1),
(7358419, 1151285, 150277, '<td valign="top">Amazing shot, if one of the birds was composited in, I sure can''t tell.  And if you got them both in one shot that is really incredible.  I think a perfect image for the book cover.</td>', 'Amazing shot, if one of the birds was composited in, I sure can''t tell.  And if you got them both in one shot that is really incredible.  I think a perfect image for the book cover.', '2015-06-08 00:24:48.000000', NULL, 1),
(7358420, 1151523, 150277, '<td valign="top">Lovely and dramatic.  I felt like I was expecting a mystery or drama rather than something non-fiction like the title seems to suggest.</td>', 'Lovely and dramatic.  I felt like I was expecting a mystery or drama rather than something non-fiction like the title seems to suggest.', '2015-06-08 00:25:30.000000', NULL, 1),
